mapper.select:
SELECT A.BOOKSET_ID AS booksetId, A.BOOKSET_NAME AS booksetName, A.ACCT_MODE AS acctMode, coalesce(D.SCH_ID, (select select sch_id from(select row_number() over() rownum, info.sch_id from BOK_SCHEME_INFO info where info.is_default = 'Y' and info.scheme_type = #{schemeType} ) where rownum = 1)) AS orgSchId, coalesce(D.SCH_NAME, (select SCH_NAME from (select row_number() over() rownum, info.SCH_NAME from BOK_SCHEME_INFO info where info.is_default = 'Y' and info.scheme_type =#{schemeType} ) where rownum = 1)) AS orgSchName,
C.BOOKSET_SCHEME_ID AS booksetSchemeId FROM BOK_BOOKSET A LEFT JOIN BOK_BOOKSET B ON B.BOOKSET_ID = A.BOOKSET_ID_TMPL LEFT JOIN BOK_BOOKSET_PLAN C ON C.BOOKSET_ID = A.BOOKSET_ID AND C.SCHEME_TYPE = #{schemeType} LEFT JOIN BOK_SCHEME_INFO D ON D.SCH_ID = C.SCHEME_ID AND D.SCHEME_TYPE = C.SCHEME_TYPE WHERE A.BOOKSET_TYPE = #{booksetType}
AND A.BOOKSET_ID IN
#{item}
ORDER BY A.BOOKSET_ID_TMPL ASC
